<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {request} from '../api'
import {confirmAction} from '../ui/confirm'
const props=defineProps<{disabled?:boolean}>()
const emit=defineEmits<{(e:'changed'):void;(e:'busy',value:boolean):void}>()
const busy=ref(false),error=ref(''),notice=ref(''),plan=ref<any>(null)
const blocked=computed(()=>plan.value?.issues.some((item:any)=>['source_not_rebuildable','invalid_snapshot','missing_history_place','missing_history_media','missing_source_record'].includes(item.code))??false)
const missingIdentity=computed(()=>plan.value?.issues.some((item:any)=>item.reason==='missing_legacy_place_binding')??false)
watch(busy,value=>emit('busy',value))
async function inspect(){if(busy.value||props.disabled)return;busy.value=true;error.value='';notice.value='';try{plan.value=await request('/admin/archive/places/maintenance/index-preview')}catch(e){error.value=String(e)}finally{busy.value=false}}
async function apply(action:'cleanup'|'rebuild'){if(!plan.value||busy.value||props.disabled||blocked.value||!await confirmAction(action==='cleanup'?'确认按此预览清理失效派生关联？保留稳定身份、手动城市、分类、历史正文与原图。':'确认按此预览重建索引及补齐历史保护引用？原始正文与手动数据保留。'))return;busy.value=true;error.value='';try{const result=await request('/admin/archive/places/maintenance/index-apply',{method:'POST',body:JSON.stringify({action,digest:plan.value.digest,confirmation:'确认索引维护'})});notice.value=`已完成：更新 ${result.records} 篇，清理 ${result.cleaned} 项，补齐 ${result.history_references_added} 项历史保护引用。`;plan.value=null;emit('changed')}catch(e){error.value=String(e);plan.value=null}finally{busy.value=false}}
</script>
<template><details class="card"><summary>索引一致性检查与安全维护</summary><p v-if="disabled&&!busy" class="muted">请先保存或放弃资源草稿，再检查和维护索引。</p><p>检查只读。执行前必须预览并确认；数据变化后需重新预览。不会删除历史正文或媒体原图。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button :disabled="busy||disabled" @click="inspect">只读检查与影响预览</button><template v-if="plan"><p v-if="blocked" class="error" role="alert">{{missingIdentity?'旧版标记缺少地点身份绑定，自动维护已暂停；请在来源文章明确选择原地点后重新预览。不会按当前同名地点推断。':'存在无法安全重建的来源或历史资源，请核对下方来源记录后重新预览；原文、历史和手动数据保留。'}}</p><p>待同步文章：{{plan.records.length}}；历史保护引用待补齐：{{plan.history_references_to_add}}；可清理关联：{{plan.cleanup.length+plan.food_detach.length}}；保留失效美食身份：{{plan.preserved_food_identities}}</p><p>{{plan.note}}</p><details><summary>影响明细</summary><p v-for="item in plan.records" :key="item.record_id">来源文章 {{item.record_id}} · 版本 {{item.expected_revision}} · {{item.indexes.join('、')}}</p><p v-for="item in plan.cleanup" :key="item.entry_id+item.media_id">失效卡片媒体关联：{{item.record_id}} / {{item.entry_id}}</p><p v-for="item in plan.food_detach" :key="item.id">失效美食地点关联：{{item.record_id}} / {{item.id}}</p><p v-for="item in plan.blocked_food" :key="item.id">保留美食地点关联：{{item.id}} · {{item.reason}}</p><p v-for="(item,i) in plan.issues" :key="i">{{item.code}} · {{item.record_id}} {{item.revision?'修订'+item.revision:''}}</p></details><button :disabled="busy||disabled||blocked" @click="apply('rebuild')">确认重建索引</button><button :disabled="busy||disabled||blocked" @click="apply('cleanup')">确认清理预览中的关联</button></template></details></template>
